<?php
declare(strict_types=1);
namespace App\Repositories;use PDO;
final readonly class BouquetRepository{public function __construct(private PDO $db){}public function all():array{return $this->db->query("SELECT b.*,COUNT(DISTINCT bc.category_id) categories_count,COUNT(DISTINCT bi.content_item_id) items_count,GROUP_CONCAT(DISTINCT c.name ORDER BY c.type,c.name SEPARATOR ', ') category_names FROM bouquets b LEFT JOIN bouquet_categories bc ON bc.bouquet_id=b.id LEFT JOIN categories c ON c.id=bc.category_id LEFT JOIN bouquet_content_items bi ON bi.bouquet_id=b.id GROUP BY b.id ORDER BY b.id DESC")->fetchAll();}public function categories():array{return $this->db->query("SELECT id,name,type,(SELECT COUNT(*) FROM content_items i WHERE i.category_id=categories.id) items_count FROM categories WHERE active=1 ORDER BY FIELD(type,'live','movie','series'),name")->fetchAll();}public function map():array{$out=[];foreach($this->db->query('SELECT bouquet_id,category_id FROM bouquet_categories') as $r)$out[(int)$r['bouquet_id']][]=(int)$r['category_id'];return $out;}}
